import sys
def solve(n, m, k, edges):
    import heapq
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        u -= 1
        v -= 1
        adj[u].append((v, w))

    pq = [(0, 0)]  # (cost, node)
    visits = [0] * n
    ans = []

    while pq and len(ans) < k:
        d, u = heapq.heappop(pq)

        visits[u] += 1
        if visits[u] > k: continue

        if u == n - 1:
            ans.append(d)
            if len(ans) == k: break

        for v, w in adj[u]:
            if visits[v] < k:
                heapq.heappush(pq, (d + w, v))

    while len(ans) < k: ans.append(-1)

    return "\n".join(map(str, ans))

if __name__ == '__main__':
    input_data = sys.stdin.read().split()
    if not input_data: exit()
    n, m, k = int(input_data[0]), int(input_data[1]), int(input_data[2])
    edges = []
    idx = 3
    for _ in range(m):
        edges.append([int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])])
        idx += 3
    print(solve(n, m, k, edges))

